/**
 * Original pipeline regressions based on the official statement-block, next-statement and yield-clause productions.
 * Comparative source: gql-compat corpus optional/gq20/next-composition and optional/gq20/next-yield. Integer positions
 * follow the unsigned-integer and non-negative-integer-specification productions.
 */
class GqlPipelineEvaluationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String BASE = "urn:gql:pipeline:";
	private static final IRI PERSON = iri("Person");
	private static final IRI KNOWS = iri("knows");
	private static final IRI NAME = iri("name");
	private static final IRI AGE = iri("age");
	private static final IRI ALICE = iri("alice");
	private static final IRI BOB = iri("bob");
	private static final IRI CAROL = iri("carol");
	private SailRepository repository;
	private RepositoryConnection connection;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		connection = repository.getConnection();
		for (IRI person : List.of(ALICE, BOB, CAROL)) {
			connection.add(person, RDF.TYPE, PERSON);
		}
		connection.add(ALICE, NAME, VF.createLiteral("Alice"));
		connection.add(BOB, NAME, VF.createLiteral("Bob"));
		connection.add(CAROL, NAME, VF.createLiteral("Carol"));
		connection.add(ALICE, AGE, VF.createLiteral(42));
		connection.add(BOB, AGE, VF.createLiteral(20));
		connection.add(CAROL, AGE, VF.createLiteral(42));
		connection.add(ALICE, KNOWS, BOB);
		connection.add(BOB, KNOWS, CAROL);
	}

	@AfterEach
	void tearDown() {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
		}
	}

	@Test
	void nextPassesAllRowsIntoTheFollowingAggregation() {
		assertThat(number("MATCH (n:Person) WHERE n.age > 30 RETURN n.name AS name "
				+ "NEXT RETURN COUNT(*) AS total", "total")).isEqualTo(2);
	}

	@Test
	void nextYieldSelectsAndRenamesColumns() {
		assertThat(number("RETURN 1 AS first, 2 AS second NEXT YIELD second AS kept RETURN kept", "kept"))
				.isEqualTo(2);
		assertThat(number("RETURN 1 AS first, 2 AS second NEXT YIELD first AS a, second AS b RETURN a + b AS total",
				"total")).isEqualTo(3);
	}

	@Test
	void nextYieldCanRenameADelimitedFieldToARegularBinding() {
		assertThat(number("RETURN 7 AS \"odd field\" NEXT YIELD \"odd field\" AS n RETURN n", "n"))
				.isEqualTo(7);
	}

	@Test
	void stageAliasesStaySeparateFromApiParameters() {
		TupleQuery query = query("RETURN 1 AS x NEXT RETURN x + $x AS total");
		query.setBinding("x", VF.createLiteral(2));
		assertThat(((Literal) rows(query).getFirst().getValue("total")).longValue()).isEqualTo(3);
		query.setBinding("x", VF.createLiteral(5));
		assertThat(((Literal) rows(query).getFirst().getValue("total")).longValue()).isEqualTo(6);
	}

	@Test
	void nextDoesNotExposeUnreturnedOrUnyieldedBindings() {
		assertThatThrownBy(() -> query("MATCH (n:Person) RETURN n.name AS name NEXT RETURN n"))
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("Undeclared variable");
		assertThatThrownBy(() -> query("RETURN 1 AS a, 2 AS b NEXT YIELD a AS renamed RETURN b"))
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("Undeclared variable");
		assertThatThrownBy(() -> query("RETURN 1 AS a NEXT YIELD a AS renamed RETURN a"))
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("Undeclared variable");
	}

	@Test
	void yieldRejectsUnknownFieldsAndDuplicateTargetNames() {
		assertThatThrownBy(() -> query("RETURN 1 AS a NEXT YIELD missing RETURN missing"))
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("Unknown YIELD field");
		assertThatThrownBy(() -> query("RETURN 1 AS a, 2 AS b NEXT YIELD a AS x, b AS x RETURN x"))
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("Duplicate YIELD binding");
	}

	@Test
	void unionCompletesBeforeTheFollowingNextStage() {
		assertThat(number("RETURN 1 AS x UNION ALL RETURN 2 AS x NEXT RETURN SUM(x) AS total", "total"))
				.isEqualTo(3);
	}

	@Test
	void eachUnionBranchReceivesTheSamePipelineInput() {
		List<BindingSet> result = rows("RETURN 3 AS x NEXT RETURN x + 1 AS n UNION ALL RETURN x + 2 AS n");
		assertThat(result.stream().map(row -> ((Literal) row.getValue("n")).longValue()).toList())
				.containsExactlyInAnyOrder(4L, 5L);
	}

	@Test
	void groupingStateDoesNotLeakIntoFollowingStages() {
		assertThat(number("MATCH (n:Person) RETURN n.age AS age, COUNT(*) AS total GROUP BY age "
				+ "NEXT FILTER total > 1 RETURN SUM(total) AS total NEXT RETURN total + 1 AS result", "result"))
						.isEqualTo(3);
	}

	@Test
	void yieldDoesNotMoveBeforeDistinctOrLimit() {
		assertThat(number("MATCH (n:Person) RETURN DISTINCT n.age AS age, n.name AS name "
				+ "NEXT YIELD age RETURN COUNT(*) AS total", "total")).isEqualTo(3);
		assertThat(column(rows("MATCH (n:Person) RETURN n.age AS age, n.name AS name ORDER BY name LIMIT 2 "
				+ "NEXT YIELD age RETURN age"), "age")).containsExactly(VF.createLiteral(42), VF.createLiteral(20));
	}

	@Test
	void laterFiltersCannotChangeWhichRowsAnEarlierLimitSelected() {
		TupleQuery filter = query("MATCH (n:Person) RETURN n ORDER BY n.name LIMIT 1 "
				+ "NEXT FILTER n = $start RETURN n");
		filter.setBinding("start", BOB);
		assertThat(rows(filter)).isEmpty();
		TupleQuery match = query("MATCH (n:Person) RETURN n ORDER BY n.name LIMIT 1 "
				+ "NEXT MATCH (n)-[:knows]->(friend) WHERE n = $start RETURN friend");
		match.setBinding("start", BOB);
		assertThat(rows(match)).isEmpty();
	}

	@Test
	void nullValuesRemainNullAcrossStages() {
		List<BindingSet> result = rows("RETURN NULL AS missing NEXT RETURN missing");
		assertThat(result).hasSize(1);
		assertThat(result.getFirst().getValue("missing")).isNull();
		assertThat(column(rows("MATCH (n:Person) OPTIONAL MATCH (n)-[:knows]->(friend) RETURN n, friend "
				+ "NEXT FILTER friend IS NULL RETURN n"), "n")).containsExactly(CAROL);
	}

	@Test
	void projectedNodeIdentitySupportsLaterMatchesAndPropertyAccess() {
		TupleQuery query = query("MATCH (n:Person) WHERE n = $start RETURN n AS selected "
				+ "NEXT MATCH (selected)-[:knows]->(friend) RETURN selected, friend.name AS name");
		query.setBinding("start", ALICE);
		List<BindingSet> result = rows(query);
		assertThat(result).hasSize(1);
		assertThat(result.getFirst().getValue("selected")).isEqualTo(ALICE);
		assertThat(result.getFirst().getValue("name")).isEqualTo(VF.createLiteral("Bob"));
	}

	@Test
	void projectedEdgeIdentityConstrainsTheFollowingMatch() {
		TupleQuery query = query("MATCH (a)-[e:knows]->(b) WHERE a = $start RETURN e AS selected "
				+ "NEXT MATCH (x)-[selected]->(y) RETURN x, y, selected");
		query.setBinding("start", ALICE);
		List<BindingSet> result = rows(query);
		assertThat(result).hasSize(1);
		assertThat(result.getFirst().getValue("x")).isEqualTo(ALICE);
		assertThat(result.getFirst().getValue("y")).isEqualTo(BOB);
		assertThat(result.getFirst().getValue("selected")).isEqualTo(VF.createTripleTerm(ALICE, KNOWS, BOB));
	}

	@Test
	void aNullEdgeCannotBeReboundInTheFollowingMatch() {
		TupleQuery query = query("MATCH (n:Person) WHERE n = $start OPTIONAL MATCH (n)-[e:knows]->(friend) RETURN e "
				+ "NEXT MATCH (a)-[e]->(b) RETURN b");
		query.setBinding("start", CAROL);
		assertThat(rows(query)).isEmpty();
	}

	@Test
	void standardLetValueAndFilterWhereSpellingsCompose() {
		assertThat(number("LET VALUE n = 7 FILTER WHERE n > 3 RETURN n NEXT LET VALUE m = n + 1 RETURN m", "m"))
				.isEqualTo(8);
	}

	@Test
	void repeatedUnionPipelinesRespectTheAlgebraConstructionBudget() {
		StringBuilder query = new StringBuilder("RETURN 1 AS x");
		for (int stage = 0; stage < 32; stage++) {
			query.append(" NEXT RETURN x AS x UNION ALL RETURN x AS x");
		}
		assertThatThrownBy(() -> query(query.toString())).isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("algebra");
	}

	@Test
	void unsignedIntegerSpellingsWorkInPagination() {
		for (String[] bounds : List.of(new String[] { "0x_1", "0b_1_0" }, new String[] { "0o_1", "0_2" },
				new String[] { "0b1", "0o2" }, new String[] { "0_1", "0x2" })) {
			assertThat(column(rows("MATCH (n:Person) RETURN n.name AS name ORDER BY name OFFSET " + bounds[0]
					+ " LIMIT " + bounds[1]), "name"))
							.containsExactly(VF.createLiteral("Bob"), VF.createLiteral("Carol"));
		}
		assertThat(rows("MATCH (n:Person) RETURN n LIMIT 0xDEAD")).hasSize(3);
		assertThat(rows("MATCH (n:Person) RETURN n OFFSET 0xE")).isEmpty();
		assertThat(rows("RETURN 1 AS n LIMIT 0x7fff_ffff_ffff_ffff")).hasSize(1);
	}

	@Test
	void unsignedIntegerSpellingsWorkInFinitePathBounds() {
		for (String bound : List.of("0x_2", "0o_2", "0b_1_0", "0_2")) {
			List<BindingSet> result = rows("MATCH (a)-[:knows]->{" + bound + "}(b) RETURN a, b");
			assertThat(result).hasSize(1);
			assertThat(result.getFirst().getValue("a")).isEqualTo(ALICE);
			assertThat(result.getFirst().getValue("b")).isEqualTo(CAROL);
		}
		assertThat(number("MATCH (a)-[:knows]->{0b1,0x2}(b) RETURN COUNT(*) AS total", "total"))
				.isEqualTo(3);
		assertThat(rows("MATCH (a)-[:knows]->{0x1E}(b) RETURN a, b")).isEmpty();
	}

	@Test
	void integerOnlyPositionsRejectFractionsExponentsSuffixesSignsAndOverflow() {
		for (String value : List.of("1.0", ".5", "1e0", "1E+0", "1M", "1F", "1D", "-1", "+1",
				"9223372036854775808", "0x8000_0000_0000_0000")) {
			assertThatThrownBy(() -> query("RETURN 1 AS n LIMIT " + value)).as("LIMIT %s", value)
					.isInstanceOf(MalformedQueryException.class);
			assertThatThrownBy(() -> query("RETURN 1 AS n OFFSET " + value)).as("OFFSET %s", value)
					.isInstanceOf(MalformedQueryException.class);
			assertThatThrownBy(() -> query("MATCH (a)-[:knows]->{" + value + "}(b) RETURN b"))
					.as("path bound %s", value)
					.isInstanceOf(MalformedQueryException.class);
		}
		assertThatThrownBy(() -> query("MATCH (a)-[:knows]->{0b10,0x1}(b) RETURN b"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> query("MATCH (a)-[:knows]->{0x21}(b) RETURN b"))
				.isInstanceOf(MalformedQueryException.class);
	}

	private TupleQuery query(String text) {
		return connection.prepareTupleQuery(QueryLanguage.GQL, text, BASE);
	}

	private List<BindingSet> rows(String text) {
		return rows(query(text));
	}

	private List<BindingSet> rows(TupleQuery query) {
		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private long number(String text, String name) {
		List<BindingSet> result = rows(text);
		assertThat(result).hasSize(1);
		return ((Literal) result.getFirst().getValue(name)).longValue();
	}

	private static List<Value> column(List<BindingSet> rows, String name) {
		List<Value> values = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			values.add(row.getValue(name));
		}
		return values;
	}

	private static IRI iri(String localName) {
		return VF.createIRI(BASE + localName);
	}
}
